"""Slow reference replay of installs, epochs and bank lifetimes."""


def replay(request, catalog):
    """Return (installs, decisions, final) computed independently."""
    releases = {item['id']: item for item in catalog}
    capacity = request['capacity']
    resident = set()
    pins = {}
    current = None
    flows = {}
    epochs = {}
    installs = []
    decisions = []

    def usage():
        ur = ue = 0
        for rid in resident:
            item = releases[rid]
            if item['mode'] == 'range':
                ur += len(item['kept_clusters'])
            else:
                ue += item['entries']
        return {'range': ur, 'exact': ue}

    def match(release, features):
        """Highest priority kept cluster matching the suffix."""
        best = None
        for cid in release['priority']:
            cluster = release['cluster_by_id'][cid]
            bounds = cluster['range']
            length = len(bounds)
            if length > len(features):
                continue
            window = features[len(features) - length:]
            if all(bounds[i][0] <= window[i] <= bounds[i][1] for i in range(length)):
                return cluster
        return best

    def predict(release, features):
        width = release['width']
        sample = list(features[:width]) + [1514] * max(0, width - len(features))
        node = 0
        while True:
            entry = release['backup'][node]
            if len(entry) == 1:
                return entry[0]
            feature, doubled, left, right = entry
            node = left if 2 * sample[feature] <= doubled else right

    position = 0
    for block in request['blocks']:
        for event in block:
            op = event[0]
            if op == 'install':
                rid = event[1]
                item = releases[rid]
                limit = capacity['range'] if item['mode'] == 'range' else capacity['exact']
                size = item['entries']
                if size > limit:
                    status = 'oversize'
                else:
                    evicted = None
                    if current is not None and pins.get(current, 0) == 0:
                        evicted = current
                    prospective = set(resident)
                    if evicted is not None:
                        prospective.discard(evicted)
                    prospective.add(rid)
                    ur = ue = 0
                    for other in prospective:
                        other_item = releases[other]
                        if other_item['mode'] == 'range':
                            ur += len(other_item['kept_clusters'])
                        else:
                            ue += other_item['entries']
                    if ur > capacity['range'] or ue > capacity['exact']:
                        status = 'busy'
                    else:
                        status = 'ok'
                        if evicted is not None:
                            resident.discard(evicted)
                        resident.add(rid)
                        current = rid
                installs.append({'at': position, 'id': rid, 'status': status,
                                 'resident': sorted(resident), 'used': usage()})
            elif op == 'open':
                rid = event[1]
                if rid in flows:
                    raise ValueError('invalid')
                if current is None:
                    raise ValueError('invalid')
                epoch = epochs.get(rid, 0)
                epochs[rid] = epoch + 1
                pins[current] = pins.get(current, 0) + 1
                flows[rid] = {'epoch': epoch, 'release': current, 'features': [],
                              'source': None, 'last': None, 'previous': None,
                              'classified': False}
            elif op == 'packet':
                rid = event[1]
                timestamp, source, length = event[2], event[3], event[4]
                state = flows.get(rid)
                if state is None:
                    raise ValueError('invalid')
                if state['last'] is not None and timestamp < state['last']:
                    raise ValueError('invalid')
                state['last'] = timestamp
                if not state['classified']:
                    release = releases[state['release']]
                    features = state['features']
                    if len(features) >= release['width'] and state['previous'] is not None and \
                            timestamp - state['previous'] > release['idle_us']:
                        decisions.append({'flow': rid, 'epoch': state['epoch'],
                                          'release': state['release'], 'at': position,
                                          'seen': len(features),
                                          'class': predict(release, features),
                                          'reason': 'idle', 'rule': None, 'start': None})
                        state['classified'] = True
                    else:
                        if state['source'] is None:
                            state['source'] = source
                        features.append(1514 + length if source == state['source'] else 1514 - length)
                        state['previous'] = timestamp
                        cluster = match(release, features)
                        if cluster is not None:
                            decisions.append({'flow': rid, 'epoch': state['epoch'],
                                              'release': state['release'], 'at': position,
                                              'seen': len(features), 'class': cluster['class'],
                                              'reason': 'segment', 'rule': cluster['id'],
                                              'start': len(features) - len(cluster['range'])})
                            state['classified'] = True
                        elif len(features) > release['packet_limit']:
                            decisions.append({'flow': rid, 'epoch': state['epoch'],
                                              'release': state['release'], 'at': position,
                                              'seen': len(features),
                                              'class': predict(release, features),
                                              'reason': 'limit', 'rule': None, 'start': None})
                            state['classified'] = True
            elif op == 'close':
                rid = event[1]
                state = flows.get(rid)
                if state is None:
                    raise ValueError('invalid')
                if not state['classified']:
                    release = releases[state['release']]
                    decisions.append({'flow': rid, 'epoch': state['epoch'],
                                      'release': state['release'], 'at': position,
                                      'seen': len(state['features']),
                                      'class': predict(release, state['features']),
                                      'reason': 'close', 'rule': None, 'start': None})
                    state['classified'] = True
                del flows[rid]
                held = state['release']
                pins[held] = pins.get(held, 0) - 1
                if pins[held] <= 0 and held != current:
                    resident.discard(held)
            position += 1
    if flows:
        raise ValueError('invalid')
    final = {'current': current, 'resident': sorted(resident), 'used': usage()}
    return installs, decisions, final
